"""1486 (#11 enemy_body_size_variants): Record-MissionCoverage-v1465.ps1 with targets taken where they stand. Every target
moved by the lab teleport refused takedowns, even after a 3 s settle with the placement made in both worlds (1476b,
1483a/b: the choke press became a parry; the teleported witch stood frozen), while the same witch at her post was choked
(1467b). Targets are therefore never moved: -TargetDefinition and the new -TargetScene REGEX (NPCs bound to a running scene
whose asset matches, from a 1.5 s scene scan on the host, e.g. a sitting activity) build a candidate list, and each
candidate is tried by standing the source -Behind it and reading where the source actually stands: the first candidate
whose stand point is reachable (within 0.35 m, height within 0.6 m) is the target (1467a's first witch put Emily inside a
cabinet). Generated by make_mission_coverage_v1486.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-MissionCoverage-v1465.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)
rep("[switch]$Perch,[string]$TargetDefinition='')", "[switch]$Perch,[string]$TargetDefinition='',[string]$TargetScene='')")
first = s.index('\n') + 1
s = s[:first] + "# 1486 (#11): targets picked in place by definition or running scene, the first with a reachable stand point. Generated by make_mission_coverage_v1486.py.\n" + s[first:]
i = s.index("     if($TargetDefinition){$cand=")
j = s.index("\n", s.index("$row.targetChosen=", i)) + 1
s = s[:i] + (
"     if($TargetDefinition-or$TargetScene){$pool=@($catalog|Where-Object {$_.unique-and$_.spawnerName})\n"
"      if($TargetDefinition){$pool=@($pool|Where-Object {$_.definition-match$TargetDefinition})}\n"
"      if($TargetScene){$sw=\"$out/$key-scene-scan.ndjson\";$sp=Start-Process \"$lab/bin/d2_runtime_probe.exe\" -ArgumentList @([string]$pids.host,'--watch-midnight','1500') -WindowStyle Hidden -RedirectStandardOutput $sw -RedirectStandardError \"$out/$key-scene-scan.err\" -PassThru;[void]$sp.WaitForExit(8000)\n"
"       $hs=@{};foreach($ln in @(Get-Content $sw -ErrorAction SilentlyContinue)){$o=$null;try{$o=$ln|ConvertFrom-Json}catch{};if(!$o){continue};foreach($in in @($o.instances)){if($in.asset-and$in.asset-match$TargetScene){foreach($bd in @($in.bindingsResearch)){if($bd.handle){$hs[[string]([uint64]$bd.handle)]=$in.asset}}}}}\n"
"       $row.sceneHandles=@($hs.Keys);$pool=@($pool|Where-Object {$hs.ContainsKey([string]([Convert]::ToUInt64(([string]$_.handle-replace'^0x',''),16)))})}\n"
"      $row.targetCandidates=@($pool|ForEach-Object {\"$($_.spawnerName)=$($_.definition)\"});if(!$pool.Count){throw 'No unique NPC matches the target filter'}\n"
"      $picked=$null;$tries=@()\n"
"      foreach($cnd in @($pool|Select-Object -First 12)){$co=$cnd.orientation;$cfx=[double]$co[0];$cfy=[double]$co[1];$cfl=[Math]::Max(.1,[Math]::Sqrt($cfx*$cfx+$cfy*$cfy));$cfx/=$cfl;$cfy/=$cfl\n"
"       $tx=[double]$cnd.position[0]-$Behind*$cfx;$ty=[double]$cnd.position[1]-$Behind*$cfy;C $source (P $tx $ty ([double]$cnd.position[2]+1.7) ([Math]::Atan2($cfy,$cfx)*180/[Math]::PI));Start-Sleep -Milliseconds 450\n"
"       $got=(Q $source '--player').candidatePosition;$err=[Math]::Sqrt([Math]::Pow([double]$got[0]-$tx,2)+[Math]::Pow([double]$got[1]-$ty,2));$dz=[Math]::Abs([double]$got[2]-[double]$cnd.position[2])\n"
"       $tries+=[pscustomobject]@{spawner=$cnd.spawnerName;err=[Math]::Round($err,2);dz=[Math]::Round($dz,2)};if($err-lt.35-and$dz-lt.6){$picked=$cnd;break}}\n"
"      $row.reachTries=$tries;if(!$picked){throw 'No candidate had a reachable stand point behind it'}\n"
"      $TargetSpawner=$picked.spawnerName;$row.targetChosen=\"$($picked.spawnerName)=$($picked.definition)\"}\n") + s[j:]
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Record-MissionCoverage-v1486.ps1').write_bytes(out.encode('utf-8'))
print('ok')
